"""Valhalla setup: generate docker-compose.yml from config.toml and check health."""

from __future__ import annotations

import hashlib
import subprocess
from pathlib import Path

import httpx

from .config import ROOT, Config, load_config

GEOFABRIK = "https://download.geofabrik.de"

COMPOSE_TEMPLATE = """\
# Generated by `drivelog valhalla compose` from config.toml. Edit config.toml, not this file.
# Normal setup: `drivelog valhalla fetch` downloads + verifies + merges the extracts into
# {data_dir}/merged.osm.pbf, which the container builds from. tile_urls is only a fallback
# used when no local PBF exists (its downloader has no retry or checksum).
services:
  valhalla:
    image: ghcr.io/valhalla/valhalla-scripted:latest
    container_name: {container}
    ports:
      - "127.0.0.1:{port}:8002"
    volumes:
      - ./{data_dir}:/custom_files
    environment:
      - tile_urls={tile_urls}
      - serve_tiles=True
      - build_elevation=False
      - build_admins=True
      - build_time_zones=True
      - force_rebuild=False
      - use_tiles_ignore_pbf=True
      - server_threads=4
    restart: unless-stopped
"""


def compose(cfg: Config, *args: str) -> list[str]:
    """`docker compose` for this config. The default compose file keeps Docker's default project name
    (so an existing container is reused); any other file gets its own project, named after its container."""
    cmd = ["docker", "compose", "-f", str(cfg.compose_path)]
    if cfg.compose_path.name != "docker-compose.yml":
        cmd += ["-p", cfg.container]
    return cmd + list(args)


def tile_urls(cfg: Config) -> list[str]:
    return [f"{GEOFABRIK}/{e}-latest.osm.pbf" for e in cfg.valhalla.get("extracts", [])]


def fetch_extracts(cfg: Config | None = None) -> list[Path]:
    """Download each extract into data/valhalla/ with resume + retry, verified against Geofabrik's .md5.

    valhalla-scripted's own downloader has no retry and happily builds from a truncated file."""
    cfg = cfg or load_config()
    out_dir = cfg.valhalla_dir / "src"  # kept out of /custom_files so Valhalla only sees merged.osm.pbf
    out_dir.mkdir(parents=True, exist_ok=True)
    paths = []
    for url in tile_urls(cfg):
        dest = out_dir / url.rsplit("/", 1)[1]
        # Downloads go to .part and replace the extract only once verified, so an older complete file
        # (Geofabrik republishes daily) is never "resumed" into a corrupt one.
        part = dest.with_name(dest.name + ".part")
        want = httpx.get(url + ".md5", follow_redirects=True, timeout=30).text.split()[0]
        for attempt in range(5):
            if dest.exists() and _md5(dest) == want:
                break
            print(f"downloading {dest.name} (attempt {attempt + 1})", flush=True)
            r = subprocess.run(["curl", "-fL", "--retry", "10", "--retry-all-errors", "-C", "-",
                                "-o", str(part), url])
            if r.returncode == 33:  # server refused range resume: start over
                part.unlink(missing_ok=True)
            elif r.returncode == 0:
                if _md5(part) == want:
                    part.replace(dest)
                    break
                part.unlink()  # complete but corrupt: resuming can't fix it
        else:
            raise RuntimeError(f"{dest.name}: checksum mismatch after retries")
        print(f"ok {dest.name}", flush=True)
        paths.append(dest)
    return paths


def merge_extracts(paths: list[Path], cfg: Config | None = None) -> Path:
    """Merge extracts into one deduplicated PBF. Overlapping extracts fed to Valhalla separately make
    valhalla_build_tiles abort on duplicated border ways (see DEBUG.md)."""
    cfg = cfg or load_config()
    merged = cfg.valhalla_dir / "merged.osm.pbf"
    if len(paths) == 1:  # nothing to merge
        import shutil

        shutil.copyfile(paths[0], merged)
        return merged
    subprocess.run(["osmium", "merge", *map(str, paths), "-o", str(merged), "--overwrite"], check=True)
    return merged


def configure(cfg: Config | None = None) -> list[str]:
    """Patch data/valhalla/valhalla.json (written by the container on first start) with the settings
    the matcher relies on. valhalla-scripted keeps existing values on restart. Restart after this."""
    import json

    cfg = cfg or load_config()
    path = cfg.valhalla_dir / "valhalla.json"
    if not path.exists():
        raise SystemExit("data/valhalla/valhalla.json not found: start the container once first.")
    c = json.loads(path.read_text())
    changes = []
    meili = c["meili"]
    # Without this, breakage_distance in requests is silently ignored (DEBUG.md, Phase 3).
    if "breakage_distance" not in meili["customizable"]:
        meili["customizable"].append("breakage_distance")
        changes.append("meili.customizable += breakage_distance")
    # 4 threads x 1 GB default tile cache doesn't fit Docker's default VM alongside matching (DEBUG.md).
    if c["mjolnir"].get("max_cache_size", 0) > 400_000_000:
        c["mjolnir"]["max_cache_size"] = 400_000_000
        changes.append("mjolnir.max_cache_size = 400 MB")
    for obj, key, val in ((c["service_limits"]["trace"], "max_search_radius", 200.0),
                          (c["service_limits"]["trace"], "max_gps_accuracy", 200.0),
                          (meili["default"], "max_search_radius", 200)):
        if obj.get(key, 0) < val:
            obj[key] = val
            changes.append(f"{key} = {val}")
    path.write_text(json.dumps(c, indent=2))
    return changes


def _md5(path: Path) -> str:
    h = hashlib.md5()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 22), b""):
            h.update(chunk)
    return h.hexdigest()


def write_compose(cfg: Config | None = None) -> None:
    cfg = cfg or load_config()
    cfg.valhalla_dir.mkdir(parents=True, exist_ok=True)
    text = COMPOSE_TEMPLATE.format(tile_urls=" ".join(tile_urls(cfg)), container=cfg.container, port=cfg.port,
                                   data_dir=cfg.valhalla_dir.relative_to(ROOT).as_posix())
    cfg.compose_path.write_text(text)


def health(cfg: Config | None = None) -> dict:
    """Service status, plus a test match of the first few points of one of your drives (if any)."""
    cfg = cfg or load_config()
    base = cfg.valhalla.get("url", "http://localhost:8002")
    out = {"version": httpx.get(f"{base}/status", timeout=10).json().get("version")}
    from .db import connect

    con = connect(cfg, read_only=True) if cfg.db_path.exists() else None
    row = con and con.execute("""SELECT drive_id FROM drives WHERE match_status IN ('ok', 'partial')
                                 AND n_points >= 3 LIMIT 1""").fetchone()
    if row:
        pts = con.execute("SELECT lat, lng FROM drive_points WHERE drive_id = ? ORDER BY seq LIMIT 3", [row[0]]).fetchall()
        r = httpx.post(f"{base}/trace_attributes", timeout=30, json={
            "shape": [{"lat": lat, "lon": lng} for lat, lng in pts], "costing": "auto", "shape_match": "map_snap",
            "filters": {"attributes": ["edge.names", "edge.way_id"], "action": "include"}})
        out["test_match_edges"] = len(r.json().get("edges", [])) if r.status_code == 200 else f"error {r.status_code}"
    if con:
        con.close()
    return out


# ---------------------------------------------------------------- coverage changes (v2)


def set_extracts(extracts: list[str], path: Path | None = None) -> None:
    """Rewrite the [valhalla] extracts list in config.toml, keeping the rest of the file as is."""
    import re

    from .config import config_path

    path = path or config_path()
    text = path.read_text()
    body = "extracts = [\n" + "".join(f'    "{e}",\n' for e in extracts) + "]"
    new, n = re.subn(r"(?ms)^extracts\s*=\s*\[.*?\]", body, text, count=1)
    if n != 1:
        raise SystemExit(f"couldn't find the extracts list in {path}")
    path.write_text(new)


def _status_ok(base: str) -> bool:
    try:
        return httpx.get(f"{base}/status", timeout=5).status_code == 200
    except httpx.HTTPError:
        return False


def _restarts(container: str) -> int:
    r = subprocess.run(["docker", "inspect", container, "--format", "{{.RestartCount}}"],
                       capture_output=True, text=True)
    return int(r.stdout.strip() or 0)


def wait_ready(cfg: Config, timeout_s: float, max_restarts: int = 3, what: str = "Valhalla") -> None:
    import time

    base = cfg.valhalla.get("url", "http://localhost:8002")
    start, last = time.monotonic(), -1.0
    while time.monotonic() - start < timeout_s:
        if _status_ok(base):
            return
        if (n := _restarts(cfg.container)) > max_restarts:
            raise RuntimeError(f"{what}: container restarted {n} times (see `docker logs {cfg.container}`)")
        mins = (time.monotonic() - start) / 60
        if mins - last >= 5:
            print(f"  waiting for {what} ({mins:.0f} min)", flush=True)
            last = mins
        time.sleep(20)
    raise RuntimeError(f"{what} not ready after {timeout_s / 60:.0f} min")


# Files valhalla-scripted derives from the PBF. Moving them aside makes the next start rebuild them.
BUILT = ["valhalla_tiles.tar", "valhalla_tiles", "admins.sqlite", "file_hashes.txt"]
# The build writes tiles to this folder and then packs them into valhalla_tiles.tar. The service reads
# only the tar (and the container starts without rebuilding while the tar exists), so the folder is a
# duplicate (~13 GB here) and is removed once a build succeeds (DECISIONS.md, v3 Phase 1).
TILE_DIR = "valhalla_tiles"


def drop_tile_dir(vdir: Path) -> bool:
    """Delete the unpacked tile folder when the tar it was packed into exists. True if removed."""
    import shutil

    if (vdir / "valhalla_tiles.tar").is_file() and (vdir / TILE_DIR).is_dir():
        shutil.rmtree(vdir / TILE_DIR)
        return True
    return False


def rebuild_tiles(cfg: Config | None = None, timeout_s: float = 6 * 3600) -> None:
    """Rebuild routing tiles from data/valhalla/merged.osm.pbf. The previous build is kept in
    data/valhalla/previous/ and restored if the new one fails."""
    import shutil

    cfg = cfg or load_config()
    vdir = cfg.valhalla_dir
    prev = vdir / "previous"
    shutil.rmtree(prev, ignore_errors=True)
    prev.mkdir()
    if cfg.compose_path.exists():  # a fresh clone has no compose file yet, so nothing is running
        subprocess.run(compose(cfg, "down"), cwd=ROOT, check=True)
    drop_tile_dir(vdir)  # the tar is the rollback copy; no need to keep both
    for name in BUILT:
        if (vdir / name).exists():
            shutil.move(str(vdir / name), str(prev / name))
    write_compose(cfg)
    subprocess.run(compose(cfg, "up", "-d"), cwd=ROOT, check=True)
    try:
        wait_ready(cfg, timeout_s, what="tile build")
    except RuntimeError:
        subprocess.run(compose(cfg, "down"), cwd=ROOT, check=True)
        for name in BUILT:
            if (vdir / name).is_dir():
                shutil.rmtree(vdir / name)
            else:
                (vdir / name).unlink(missing_ok=True)
            if (prev / name).exists():
                shutil.move(str(prev / name), str(vdir / name))
        subprocess.run(compose(cfg, "up", "-d"), cwd=ROOT, check=True)
        raise
    changes = configure(cfg)
    if changes:
        subprocess.run(compose(cfg, "restart"), cwd=ROOT, check=True)
        wait_ready(cfg, 900)
    drop_tile_dir(vdir)


def disk_usage(path: Path | None = None) -> int:
    path = path or load_config().valhalla_dir
    return sum(p.stat().st_size for p in path.rglob("*") if p.is_file() and not p.is_symlink())
